/**
 * Omni-Vault · cloud vault server (generated by vault_extractor).
 *
 * Hosts the lifted core logic and the wasm bytecode. Serves the handshake and
 * the encrypted RPC channel. This process — and only this process — ever sees
 * the business logic in executable form.
 *
 * Omni-Vault：只要不把代码交出去，就绝对没有人能逆向它。
 */
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  HandshakeServer,
  verifyToken,
  scopeAllows,
  ed25519FromPrivate,
  ed25519FromPublic,
  x25519FromPrivate,
  x25519FromPublic,
  b64,
  shannonEntropy,
  VaultError,
  type ServerSessionState,
  type X25519Pair,
} from "__OMNI_SECURITY__/index.ts";
import * as Lifted from "./lifted.ts";
import { WASM_DELEGATES } from "./wasm-delegates.ts";

const here = dirname(fileURLToPath(import.meta.url));
const keys = JSON.parse(readFileSync(join(here, "server-keys.json"), "utf8"));
const config = JSON.parse(readFileSync(join(here, "server-config.json"), "utf8"));

const signPrivate = ed25519FromPrivate(b64.dec(keys.signPrivateDer));
const verifyKey = ed25519FromPublic(b64.dec(keys.signPublicDer));

const staticPriv = x25519FromPrivate(b64.dec(keys.x25519PrivateDer));
const staticPubDer = b64.dec(keys.x25519PublicDer);
const serverStaticPair: X25519Pair = {
  private: staticPriv,
  public: x25519FromPublic(staticPubDer),
  privateDer: b64.dec(keys.x25519PrivateDer),
  publicDer: staticPubDer,
};

const hs = new HandshakeServer({
  signPrivate,
  serverStaticPair,
  verifyToken: (token: string) => verifyToken(token, verifyKey),
});

const sessions = new Map<string, ServerSessionState>();

function readBody(req: IncomingMessage): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks)));
    req.on("error", reject);
  });
}

function fail(res: ServerResponse, err: unknown): void {
  const ve = err instanceof VaultError ? err : new VaultError("E_INTERNAL", String((err as Error)?.message ?? err), 500);
  const body = JSON.stringify({ code: ve.code, message: ve.message });
  res.writeHead(ve.httpStatus, { "content-type": "application/json" });
  res.end(body);
}

async function handleHandshake(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = (await readBody(req)).toString("utf8");
  const hello = JSON.parse(body);
  const { welcome, state } = hs.handleHello(hello);
  sessions.set(state.sid, state);
  console.log(`[vault-cloud] handshake ok sid=${state.sid.slice(0, 8)} scope=${state.claims.scope.join(",")}`);
  res.writeHead(200, { "content-type": "application/json" });
  res.end(JSON.stringify(welcome));
}

async function handleRpc(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const frame = await readBody(req);
  const sid = String(req.headers["x-omni-sid"] ?? "");
  const state = sessions.get(sid);
  if (!state) throw new VaultError("E_SESSION", "unknown or expired session", 401);

  const envelope = JSON.parse(state.session.open(frame).toString("utf8"));
  if (!state.verified) {
    if (!envelope.proof) throw new VaultError("E_PROOF", "identity proof required on the first call", 401);
    hs.verifyProof(state, envelope.proof, sid, envelope.callId);
  }
  if (!scopeAllows(state.claims, envelope.fn)) {
    throw new VaultError("E_SCOPE", `token scope does not include "${envelope.fn}"`, 403);
  }

  const delegate = WASM_DELEGATES[envelope.fn] ?? Lifted.__VAULT_FUNCTIONS[envelope.fn];
  if (!delegate) throw new VaultError("E_NOFN", `no cloud function named "${envelope.fn}"`, 404);

  const result = await Promise.resolve(delegate.apply(null, envelope.args ?? []));
  const reply = state.session.seal(Buffer.from(JSON.stringify({ ok: true, callId: envelope.callId, result }), "utf8"));
  console.log(
    `[vault-cloud] rpc ${envelope.fn}(${JSON.stringify(envelope.args).slice(0, 64)}) ` +
      `frame=${frame.length}B entropy=${shannonEntropy(frame).toFixed(2)}bit/B answer=${reply.length}B`,
  );
  res.writeHead(200, { "content-type": "application/octet-stream" });
  res.end(reply);
}

const server = createServer(async (req, res) => {
  try {
    if (req.method === "POST" && req.url === "/osh") return await handleHandshake(req, res);
    if (req.method === "POST" && req.url === "/orpc") return await handleRpc(req, res);
    res.writeHead(404, { "content-type": "text/plain" });
    res.end("not found");
  } catch (err) {
    fail(res, err);
  }
});

process.on("SIGINT", () => process.exit(0));

server.listen(config.port, "127.0.0.1", () => {
  const fns = [...Object.keys(WASM_DELEGATES), ...Object.keys(Lifted.__VAULT_FUNCTIONS)];
  console.log(`[vault-cloud] listening on ${config.origin}`);
  console.log(`[vault-cloud] core logic hosted: ${fns.join(", ")}`);
  console.log(`[vault-cloud] pricing.wasm = ${readFileSync(join(here, "pricing.wasm")).length} bytes of bytecode`);
  console.log("[vault-cloud] Omni-Vault：只要不把代码交出去，就绝对没有人能逆向它。");
});
